+ // Computes, on the calling thread, out[i] = in[0] + ... + in[i] for i < n, and
+ // hist[b] = number of i < n with (in[i] & 255) == b for b < 256. Neither out nor
+ // hist is zeroed by the caller. n is any size from 0 to 20'000'000; the sums
+ // never overflow int64.
+ constexpr int SUBS = 8;
+ constexpr int PREFETCH_DISTANCE = 96;
+ extern "C" void scan_and_histogram(const int64_t* __restrict__ in, int64_t* __restrict__ out, size_t n, uint64_t* __restrict__ hist) {
+     uint32_t sub_hist[SUBS][256] = {};
+     int64_t sum = 0;
+     size_t i = 0;
+     int sub_idx = 0;
+     constexpr int SUBS_MASK = SUBS - 1;
+     for (; i + 8 <= n; i += 8) {
+         __builtin_prefetch(in + i + PREFETCH_DISTANCE, 0, 1);
+         int64_t v0 = in[i];
+         int64_t v1 = in[i+1];
+         int64_t v2 = in[i+2];
+         int64_t v3 = in[i+3];
+         int64_t v4 = in[i+4];
+         int64_t v5 = in[i+5];
+         int64_t v6 = in[i+6];
+         int64_t v7 = in[i+7];
+         sum += v0; out[i] = sum; sub_hist[sub_idx][(uint8_t)v0]++; sub_idx = (sub_idx + 1) & SUBS_MASK;
+         sum += v1; out[i+1] = sum; sub_hist[sub_idx][(uint8_t)v1]++; sub_idx = (sub_idx + 1) & SUBS_MASK;
+         sum += v2; out[i+2] = sum; sub_hist[sub_idx][(uint8_t)v2]++; sub_idx = (sub_idx + 1) & SUBS_MASK;
+         sum += v3; out[i+3] = sum; sub_hist[sub_idx][(uint8_t)v3]++; sub_idx = (sub_idx + 1) & SUBS_MASK;
+         sum += v4; out[i+4] = sum; sub_hist[sub_idx][(uint8_t)v4]++; sub_idx = (sub_idx + 1) & SUBS_MASK;
+         sum += v5; out[i+5] = sum; sub_hist[sub_idx][(uint8_t)v5]++; sub_idx = (sub_idx + 1) & SUBS_MASK;
+         sum += v6; out[i+6] = sum; sub_hist[sub_idx][(uint8_t)v6]++; sub_idx = (sub_idx + 1) & SUBS_MASK;
+         sum += v7; out[i+7] = sum; sub_hist[sub_idx][(uint8_t)v7]++; sub_idx = (sub_idx + 1) & SUBS_MASK;
+     }
+     for (; i < n; ++i) {
+         int64_t v = in[i];
+         sum += v; out[i] = sum; sub_hist[sub_idx][(uint8_t)v]++; sub_idx = (sub_idx + 1) & SUBS_MASK;
+     }
+     for (int b = 0; b < 256; ++b) {
+         uint64_t total = 0;
+         for (int s = 0; s < SUBS; ++s)
+             total += sub_hist[s][b];
+         hist[b] = total;
+     }
+ }
 // OMEGA-BLOCK-END
